// ---------- the client ----------
const activeInboxes = inboxes.filter(i => i.isActive && i.status === 'ACTIVE');
const notActiveInboxes = inboxes.filter(i => !i.isActive);
const activeCapacity = activeInboxes.reduce((s, i) => s + i.dailyLimit, 0);
const notActiveCapacity = notActiveInboxes.reduce((s, i) => s + i.dailyLimit, 0);
const minRatio = STANDARD.flags.reserve_short.reserve_ratio_below;
const reserveRatio = activeCapacity ? notActiveCapacity / activeCapacity : null;
// A client with nothing active yet is still warming its first inboxes: exempt.
const reserveShort = activeCapacity > 0 && reserveRatio < minRatio;
const avgLimit = activeInboxes.length ? activeCapacity / activeInboxes.length : 0;
const shortInboxes = reserveShort && avgLimit ? Math.ceil((activeCapacity * minRatio - notActiveCapacity) / avgLimit) : 0;
const rollup = { activeInboxes: activeInboxes.length, activeCapacity, notActiveInboxes: notActiveInboxes.length, notActiveCapacity, reserveRatio, reserveShort, shortInboxes };

sd.cw.domainRows = domains;
sd.cw.clientRow = rollup;
sd.results.push({
  client: String(cw.clientName || ''),
  clientRecId: String(cw.clientRecId || ''),
  isPool: !!cw.isPool,
  clientChannel: String(cw.clientChannel || ''),
  clientReports: !!cw.clientReports,
  full, live,
  twoLanguage: inboxes.some(i => i.hasLanguage),
  inboxes: inboxes.length,
  rollup,
  domains: domains.map(d => ({ domain: d.domain, active: d.active, flags: d.flags, reasons: d.reasons })),
  emergencies: domains.reduce((a, d) => a.concat(d.emergency), []),
  changes,
  failed,
});

return [{ json: { inboxes: inboxes.length, domains: domains.length } }];

const sd = $getWorkflowStaticData('global');
const cw = $('Loop Over Clients').first().json;
const r = sd.cw.clientRow;
return [{
  json: {
    id: String(cw.clientRecId),
    'Active Mailboxes': r.activeInboxes,
    'Active Capacity': r.activeCapacity,
    'Not Active Mailboxes': r.notActiveInboxes,
    'Not Active Capacity': r.notActiveCapacity,
    // A percent field stores the fraction; 0.5 renders as 50%. No active capacity has no ratio: 0.
    'Reserve Ratio': r.reserveRatio == null ? 0 : r.reserveRatio,
    'Last Inbox Review': $now.toISO(),
  },
}];

// Close one client: what the run read and what the Hub took join the client's entry for the report, the client
// row write's failure joins its errors, and the scratch space is dropped before the next client (it can hold the
// whole read-back, which must never be saved with the workflow).
const sd = $getWorkflowStaticData('global');
const cw = $('Loop Over Clients').first().json;
const res = (sd.results || [])[(sd.results || []).length - 1];
if (res && res.client === String(cw.clientName || '')) {
  const st = sd.cw && sd.cw.stats;
  res.read = { statsPages: st ? (st.pages || 0) : null, statsFailedPages: st ? st.failedPages : 0, statsFrom: st ? st.start : '', statsTo: st ? st.end : '' };
  res.hub = { client: 0 };
  let out = [];
  try { out = $('Update Client').all().map(i => (i && i.json) || {}); } catch (e) {}
  const errors = out.filter(j => j.error).length;
  res.hub.client = out.length - errors;
  if (!out.length) res.failed.push('client row: the write returned nothing');
  else if (errors) res.failed.push('client row: the write failed');
}
delete sd.cw;
return [{ json: { done: true } }];

